        wheel_torque_nm[2] = 0.0;
        wheel_torque_nm[3] = 0.0;
        spacecraft_residual_nm->x = 0.0;
        spacecraft_residual_nm->y = 0.0;
        spacecraft_residual_nm->z = 0.0;
        return ADCS_E_RANGE;
    }
}

for (i = 0; i < 4; i++) {
    wheel_torque_nm[i] = amplitude_nm;
}

spacecraft_residual_nm->x = 0.0;
spacecraft_residual_nm->y = 0.0;
spacecraft_residual_nm->z = 0.0;
for (i = 0; i < 4; i++) {
    spacecraft_residual_nm->x -= axes[i].x * wheel_torque_nm[i];
    spacecraft_residual_nm->y -= axes[i].y * wheel_torque_nm[i];
    spacecraft_residual_nm->z -= axes[i].z * wheel_torque_nm[i];
}

return ADCS_OK;
}
